  "deck.prep.desc": "Sha’ban and getting ready for the month.",
  "deck.prep.name": "Preparing for Ramadan",
  "deck.quranfacts.desc": "Surahs, juz and the verses behind well-known virtues.",
  "deck.quranfacts.name": "Quran facts",
  "deck.sunnah.desc": "How the Prophet ﷺ fasted, ate suhoor and broke his fast.",
  "deck.sunnah.name": "Sunnahs of fasting",
